// Tomorrow, in the CLIENT's timezone — a hotel in another country must not get Belgrade's "tomorrow".
const cfg = $('Config').first().json;
const c = $input.first().json;
const tz = c.timezone || 'Europe/Belgrade';
const start = DateTime.now().setZone(tz).plus({ days: cfg.daysAhead }).startOf('day');
return [{ json: Object.assign({}, c, { tz, dryRun: !!cfg.dryRun,
  timeMin: start.toISO(), timeMax: start.plus({ days: cfg.windowDays }).toISO() }) }];

// Join tomorrow's calendar events to guest rows by EventID. Output is EITHER one alert item
// OR queue items (never both), so exactly one branch reaches the loop again.
const client = $('Window').first().json;
const evs  = $('Tomorrows Events').all().map(i => i.json || {});
const rows = $('Guest Rows').all().map(i => i.json || {});
const failed = evs.find(j => j.error) ? 'the calendar' : (rows.find(j => j.error) ? 'the reservations database' : null);
if (failed) {
  const err = (evs.concat(rows).find(j => j.error) || {}).error;
  return [{ json: { alert: true, account_id: client.account_id,
    message: 'Reminder planner could not read ' + failed + ' for ' + (client.business_name || ('account ' + client.account_id)) +
             '. Reminders for this hotel are not being queued. Error: ' + String((err && err.message) || err).slice(0, 200) } }];
}
const byEvent = new Map(rows.filter(r => r.EventID).map(r => [String(r.EventID).trim(), r]));
// The conversation the guest booked FROM beats the phone they typed (often local-format or a
// different number). Links exist for bookings made after 2026-09-24 via WhatsApp.
const links = new Map($('Booking Links').all().map(i => i.json || {}).filter(l => l.event_id).map(l => [l.event_id, l]));
const out = [];
for (const e of evs) {
  if (!e.id || !e.start || e.status === 'cancelled') continue;          // alwaysOutputData gives {} when empty
  const r = byEvent.get(e.id), link = links.get(e.id) || {};
  const phone = String(link.whatsapp_phone || (r && r.PhoneNumber) || '').trim();
  const conv = link.conversation_id ? String(link.conversation_id) : '';
  out.push({ json: {
    alert: false, doInsert: !client.dryRun, account_id: client.account_id, kind: 'prearrival', event_id: e.id,
    guest_name: r ? String(r.Name || '').trim() : '', guest_phone: phone, room: r ? String(r.RoomNumber || '').trim() : '',
    conversation_id: conv,
    checkin_at: e.start.dateTime || (e.start.date + 'T00:00:00Z'),
    status: (phone || conv) ? 'pending' : 'skipped',
    detail: (!r && !conv) ? 'calendar event has no row in the guest sheet (added by hand?)'
          : ((phone || conv) ? (conv ? 'from booking conversation' : 'typed phone only (no booking conversation recorded)') : 'booking has no phone number'),
    summary: e.summary || '' } });
}
if (!out.length) out.push({ json: { alert: false, doInsert: false, noop: true, account_id: client.account_id,
  kind: 'prearrival', event_id: '', checkin_at: new Date().toISOString(), status: 'skipped' } });
return out;
